**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[4][4];
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            plik >> m[i][j];
    cout << "Sumy wierszy:" << endl;
    for (int i = 0; i < 4; i++) {
        int s = 0;
        for (int j = 0; j < 4; j++) s += m[i][j];
        cout << "   Wiersz " << i + 1 << ": " << s << endl;
    }
    cout << "Sumy kolumn:" << endl;
    for (int j = 0; j < 4; j++) {
        int s = 0;
        for (int i = 0; i < 4; i++) s += m[i][j];
        cout << "   Kolumna " << j + 1 << ": " << s << endl;
    }
    return 0;
}
```

Weryfikacja:
- Wiersze: 3+7+1+4=15, 2+8+6+3=19, 9+4+2+7=22, 5+1+3+6=15
- Kolumny: 3+2+9+5=19, 7+8+4+1=20, 1+6+2+3=12, 4+3+7+6=20
